<?php declare(strict_types=1);
require_once __DIR__.'/../../../src/Finance/Balance/BalanceAnnualSourceCatalogue.php';
$sourceCatalogue=new \Kulturhus\Verein\BalanceAnnualSourceCatalogue($db,(string)$_SESSION['actor']);$sourceCataloguePage=null;$sourceCatalogueError='';$sourceCatalogueRow=null;$choice=null;$selected=input($old,'source_type')!==''&&input($old,'source_id')!==''?input($old,'source_type').':'.input($old,'source_id'):input($_GET,'balance_source');
$sourceCatalogueInput=in_array(input($old,'action'),['balance-source-import','balance-source-correct'],true)?$old:$_GET;$sourceFilterRaw=[];foreach(\Kulturhus\Verein\BalancePeriodSourceQuery::FIELDS as$key)$sourceFilterRaw[$key]=input($sourceCatalogueInput,$key);$sourceKind=explode(':',$selected,2)[0]??'invoice';if(!in_array($sourceKind,['invoice','transaction','depreciation'],true))$sourceKind='invoice';
try{
 if(array_key_exists('balance_source',$sourceCatalogueInput)&&!is_string($sourceCatalogueInput['balance_source']))throw new DomainException('Vollständigen Belegbezug prüfen.',422);
 $sourceCataloguePage=$sourceCatalogue->page($year,$sourceCatalogueInput,$sourceKind);$sourceFilterRaw=$sourceCataloguePage['query'];
 if($selected!==''){[$sourceSelectedType,$sourceSelectedId]=array_pad(explode(':',$selected,2),2,'');$sourceCatalogueRow=$sourceCatalogue->selected($year,$sourceSelectedType,$sourceSelectedId);$choice=['type'=>$sourceCatalogueRow['type'],'id'=>$sourceCatalogueRow['id'],'date'=>$sourceCatalogueRow['performance_date'],'name'=>($sourceCatalogueRow['display_number']!==''?$sourceCatalogueRow['display_number'].' · ':'').$sourceCatalogueRow['description'],'owner_year'=>$sourceCatalogueRow['owner_year'],'owner_period'=>$sourceCatalogueRow['owner_period']];}
}catch(DomainException $ex){$sourceCatalogueError=$ex->getMessage();if(!headers_sent())http_response_code(in_array($ex->getCode(),[403,404,422],true)?$ex->getCode():422);$choice=null;}
$sourceKinds=['invoice'=>'Rechnungen und Beiträge','transaction'=>'Bankumsätze','depreciation'=>'Anlagenwerte'];$sourceStates=['all'=>'Alle Belege','open'=>'Noch nicht übernommen','current'=>'In diesem Jahr','other'=>'Anderer Abschluss'];$sourceDirections=['all'=>'Alle Richtungen','in'=>'Eingang','out'=>'Ausgang'];
$sourceCatalogueUrl=static function(array $query,?string $selection=null)use($year):string{return url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year]+($selection===null?[]:['balance_source'=>$selection])+$query).'#balance-sources';};
$sourceOwnerLabel=static function(array $row)use($year,$annualSourceText):string{if($row['owner_period']!==null)return $annualSourceText('In einem anderen Abschluss übernommen');if($row['owner_year']===null)return $annualSourceText('Noch nicht im Journal übernommen');if((int)$row['owner_year']===$year)return $annualSourceText('In diesem Kalenderjahr übernommen');return $annualSourceText('In einem anderen Abschluss übernommen').' · '.$row['owner_year'];};
?>
<div data-annual-source-catalogue>
<?php if($sourceCatalogueRow!==null): ?><section class="card" data-annual-source-selected><h3><?= e($annualSourceText('Ausgewähltes Original')) ?></h3><p><?= e((!empty($sourceCatalogueRow['system_label'])?$annualSourceText(trim($sourceCatalogueRow['system_label'],' ·')).' · ':'').($sourceCatalogueRow['display_number']!==''?$sourceCatalogueRow['display_number'].' · ':'').$sourceCatalogueRow['description']) ?></p><p><?= e($sourceOwnerLabel($sourceCatalogueRow)) ?></p><p><?= e($annualSourceText('Der ausgewählte Beleg bleibt unabhängig von Suchseite und Filtern ausdrücklich ausgewählt.')) ?></p></section><?php endif ?>
