<p><?= e($annualSourceText('Alle relevanten Originale bleiben über Suche und Seiten erreichbar. Eine Übernahmemarkierung ersetzt keine aktuelle Prüfung des Belegs.')) ?></p>
<form method="get" class="card" data-annual-source-search><?= hidden('view','finance').hidden('tab','tax').hidden('balance','1').hidden('balance_year',(string)$year).hidden('source_page','1').($selected!==''?hidden('balance_source',$selected):'') ?>
<div class="form-grid"><label><?= e($annualSourceText('Belegart')) ?><select class="form-control" name="source_kind"><?php foreach($sourceKinds as$value=>$label): ?><option value="<?= e($value) ?>" <?= ($sourceFilterRaw['source_kind']?:$sourceKind)===$value?'selected':'' ?>><?= e($annualSourceText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($annualSourceText('Name, Rechnungsnummer oder Beschreibung suchen')) ?><input class="form-control" type="search" name="source_q" maxlength="200" value="<?= e($sourceFilterRaw['source_q']) ?>"></label>
<label><?= e($annualSourceText('Übernahme ins Journal')) ?><select class="form-control" name="source_state"><?php foreach($sourceStates as$value=>$label): ?><option value="<?= e($value) ?>" <?= ($sourceFilterRaw['source_state']?:'all')===$value?'selected':'' ?>><?= e($annualSourceText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($annualSourceText('Richtung')) ?><select class="form-control" name="source_direction"><?php foreach($sourceDirections as$value=>$label): ?><option value="<?= e($value) ?>" <?= ($sourceFilterRaw['source_direction']?:'all')===$value?'selected':'' ?>><?= e($annualSourceText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($annualSourceText('Beleg- oder Buchungsdatum von')) ?><input class="form-control" type="date" name="source_from" value="<?= e($sourceFilterRaw['source_from']) ?>"></label><label><?= e($annualSourceText('Beleg- oder Buchungsdatum bis')) ?><input class="form-control" type="date" name="source_to" value="<?= e($sourceFilterRaw['source_to']) ?>"></label>
<label><?= e($annualSourceText('Genauer Betrag ohne Vorzeichen (Euro)')) ?><input class="form-control" inputmode="decimal" name="source_amount" value="<?= e($sourceFilterRaw['source_amount']) ?>"></label></div>
<p class="form-text"><?= e($annualSourceText('Beträge ohne Tausendertrennzeichen angeben. Den Geldfluss über die Richtung auswählen. Anlagenwerte ohne Betrags- und Richtungsfilter suchen.')) ?></p><button class="btn btn-solid theme-primary"><?= e($annualSourceText('Originale suchen')) ?></button> <a class="btn btn-outline" href="<?= e($sourceCatalogueUrl(['source_kind'=>$sourceFilterRaw['source_kind']?:$sourceKind],$selected?:null)) ?>"><?= e($annualSourceText('Suche zurücksetzen')) ?></a></form>
<?php if($sourceCatalogueError!==''): ?><p role="alert"><?= e($annualSourceText($sourceCatalogueError)) ?></p><?php endif ?>
