<p role="status" data-annual-source-count><?= $sourceCataloguePage['total'] ?> · <?= e($annualSourceText($sourceKinds[$sourceQuery['source_kind']])) ?> · <?= e($annualSourceText('Seite')) ?> <?= $sourceCataloguePage['page'] ?> / <?= $sourceCataloguePage['pages'] ?></p>
<p><?= e($annualSourceText('Rechnungen und Beiträge')) ?> <?= $sourceCataloguePage['counts']['invoice'] ?> · <?= e($annualSourceText('Bankumsätze')) ?> <?= $sourceCataloguePage['counts']['transaction'] ?> · <?= e($annualSourceText('Anlagenwerte')) ?> <?= $sourceCataloguePage['counts']['depreciation'] ?></p>
<?php if(!$sourceCataloguePage['rows']): ?><p><?= e($annualSourceText('Für diese Suche wurden keine passenden Originale gefunden.')) ?></p><?php endif ?>
