<?php foreach($sourceCataloguePage['rows']as$sourceRow): ?><article class="card" data-annual-source-row="<?= e($sourceRow['type'].':'.$sourceRow['id']) ?>"><h3><?= e((!empty($sourceRow['system_label'])?$annualSourceText(trim($sourceRow['system_label'],' ·')).' · ':'').($sourceRow['display_number']!==''?$sourceRow['display_number'].' · ':'').$sourceRow['description']) ?></h3><p><?= e(dateDe($sourceRow['date'])) ?><?= $sourceRow['amount_cents']!==null?' · '.e($balanceMoney($sourceRow['amount_cents'])):'' ?></p><?php if($sourceRow['performance_date']!==$sourceRow['document_date']): ?><p><?= e($annualSourceText('Geliefert oder geleistet am')) ?> <?= e(dateDe($sourceRow['performance_date'])) ?></p><?php endif ?><p><?= e($sourceOwnerLabel($sourceRow)) ?></p><a class="btn btn-outline" data-annual-source-choice href="<?= e($sourceCatalogueUrl($sourceQuery,$sourceRow['type'].':'.$sourceRow['id'])) ?>"><?= e($annualSourceText('Diesen ursprünglichen Beleg prüfen')) ?></a></article><?php endforeach ?>
<?= $sourceCataloguePagesHtml ?>
